CREATE TABLE password_reset_codes (id UUID PRIMARY KEY,user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,code_hash VARCHAR(64) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,expires_at TIMESTAMP WITH TIME ZONE NOT NULL,used_at TIMESTAMP WITH TIME ZONE NULL,invalidated_at TIMESTAMP WITH TIME ZONE NULL,attempts INTEGER NOT NULL DEFAULT 0,max_attempts INTEGER NOT NULL,CONSTRAINT password_reset_codes_attempts_check CHECK (attempts >= 0 AND attempts <= max_attempts),CONSTRAINT password_reset_codes_max_attempts_check CHECK (max_attempts > 0));
CREATE INDEX idx_password_reset_codes_user_id ON password_reset_codes(user_id); CREATE INDEX idx_password_reset_codes_expires_at ON password_reset_codes(expires_at);
